import{_ as e,o as a,c as r,a5 as n}from"./chunks/framework.CXroN2RO.js";const s="/study/images/graphics/rigs-and-skinning.svg",p=JSON.parse('{"title":"リグとスキニングの基本 — 骨の姿勢でメッシュを動かす","description":"","frontmatter":{"title":"リグとスキニングの基本 — 骨の姿勢でメッシュを動かす","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"腕を曲げる例から、ボーンとジョイントの階層、リグ、バインド姿勢、頂点ウェイト、スキニングを説明する。FK・IKと、剛体の動きとの役割も比べる。","aliases":["リグ","rig","ボーン","bone","ジョイント","joint","スケルトン","skeleton","バインドポーズ","bind pose","スキニング","skinning","ウェイト","FK","IK","逆運動学"],"verification":"Unity 6.0のSkinned Mesh Renderer・IKとKhronosのglTF 2.0スキン仕様に照合（2026-11-07）"}},"headers":[],"relativePath":"graphics/basics/rigs-and-skinning.md","filePath":"graphics/basics/rigs-and-skinning.md"}'),i={name:"graphics/basics/rigs-and-skinning.md"};function o(h,t,d,l,c,g){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="リグとスキニングの基本-—-骨の姿勢でメッシュを動かす" tabindex="-1">リグとスキニングの基本 — 骨の姿勢でメッシュを動かす <a class="header-anchor" href="#リグとスキニングの基本-—-骨の姿勢でメッシュを動かす" aria-label="Permalink to &quot;リグとスキニングの基本 — 骨の姿勢でメッシュを動かす&quot;">​</a></h1><p>キャラクターが肘を曲げると、腕の表面も曲がります。<a href="/study/graphics/basics/models-and-meshes.html">メッシュ</a>の頂点を一つずつ手で動かす代わりに、骨格の姿勢と、各頂点がどの骨の影響を受けるかを指定して、メッシュを変形できます。ここでは腕を二つの部分に分けた例を使います。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/class-SkinnedMeshRenderer.html" target="_blank" rel="noreferrer">UnityのSkinned Mesh Renderer</a></p><h2 id="ボーンとジョイントを階層にする" tabindex="-1">ボーンとジョイントを階層にする <a class="header-anchor" href="#ボーンとジョイントを階層にする" aria-label="Permalink to &quot;ボーンとジョイントを階層にする&quot;">​</a></h2><p><strong>ボーン</strong>は、骨格を構成する部品です。肩、肘、手首など、関節を表す<strong>ジョイント</strong>を親子につなげて、姿勢を扱います。上腕を回すと、その子に当たる前腕や手のワールド上の位置も変わります。骨と関節のデータの持ち方や名前は、ツールや形式で異なります。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/InverseKinematics.html" target="_blank" rel="noreferrer">Unityの骨格と関節</a> · <a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#joint-hierarchy" target="_blank" rel="noreferrer">glTFのジョイント階層</a></p><p>この骨格と、動かすための操作用部品や制約などを組み合わせた仕組みを<strong>リグ</strong>と呼びます。制作画面では骨や操作用の形を表示して編集します。実際のキャラクターの表面は、リグの姿勢を使って変形したメッシュから描きます。<a href="https://docs.unity3d.com/Packages/com.unity.animation.rigging@1.2/manual/RiggingWorkflow.html" target="_blank" rel="noreferrer">Unityのリグの構成</a> · <a href="/study/graphics/basics/models-and-meshes.html">モデルとメッシュ</a></p><h2 id="基準の姿勢と、動かした後の姿勢" tabindex="-1">基準の姿勢と、動かした後の姿勢 <a class="header-anchor" href="#基準の姿勢と、動かした後の姿勢" aria-label="Permalink to &quot;基準の姿勢と、動かした後の姿勢&quot;">​</a></h2><p>メッシュと骨格を対応付けるときの基準を、**バインド姿勢（バインドポーズ）**と呼びます。例えば腕を伸ばした状態で対応を作り、そこから肘を曲げた姿勢への変化を計算します。アニメーションが再生する姿勢と、この基準の情報を合わせて使います。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/class-SkinnedMeshRenderer.html" target="_blank" rel="noreferrer">Unityのバインド姿勢とスキン</a></p><p>glTFには、ジョイントの一覧と、頂点を各ジョイントと同じ基準で扱うための<strong>逆バインド行列</strong>を記録する仕組みがあります。行列の役割を確認すると、メッシュの頂点を現在の骨格の姿勢へ変換する流れを追えます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#skins" target="_blank" rel="noreferrer">glTFのスキン</a> · <a href="/study/graphics/basics/transforms-and-cameras.html">座標変換の基礎</a></p><figure class="study-figure"><img src="'+s+'" alt="左は腕を伸ばした基準姿勢、右は前腕を曲げた姿勢の概念図。上腕と前腕の変換に合わせてメッシュの輪郭が変わる。肘付近の頂点は上腕0.4、前腕0.6のウェイトを使う例で示している。" width="760" height="490" loading="lazy"><figcaption>骨格と表面を一緒に描いた説明用の変形図です。<a href="/study/images/graphics/rigs-and-skinning.svg" target="_blank" rel="noopener noreferrer">骨格とスキニングの図を拡大</a></figcaption></figure><h2 id="頂点ごとに、影響する骨と重みを持つ" tabindex="-1">頂点ごとに、影響する骨と重みを持つ <a class="header-anchor" href="#頂点ごとに、影響する骨と重みを持つ" aria-label="Permalink to &quot;頂点ごとに、影響する骨と重みを持つ&quot;">​</a></h2><p><strong>スキニング</strong>は、骨格の変換を使ってメッシュを変形する処理です。各頂点には、影響するジョイントの番号と、その影響の大きさを表す**ウェイト（重み）**を持たせます。肘の近くでは上腕と前腕の両方の影響を受けるようにすると、境目をつないで動かせます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#skinned-mesh-attributes" target="_blank" rel="noreferrer">glTFのスキニング用属性</a></p><table tabindex="0"><thead><tr><th>頂点の例</th><th>上腕Aの重み</th><th>前腕Bの重み</th><th>この例の動き</th></tr></thead><tbody><tr><td>上腕の中央</td><td>1.0</td><td>0.0</td><td>上腕側の変換に従う。</td></tr><tr><td>肘の近く</td><td>0.4</td><td>0.6</td><td>二つの変換による位置を混ぜる。</td></tr><tr><td>手首側</td><td>0.0</td><td>1.0</td><td>前腕側の変換に従う。</td></tr></tbody></table><p><strong>線形ブレンドスキニング</strong>では、各ジョイントの変換で得られる頂点位置を重み付きで混ぜます。例えば、同じ頂点がAの変換では<code>(2, 0)</code>、Bの変換では<code>(2, 1)</code>へ来る説明用の2次元例なら、重み0.4と0.6で結果は<code>(2, 0.6)</code>です。実際の3Dでは基準の変換や法線の扱いも含めて計算します。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#skinned-mesh-attributes" target="_blank" rel="noreferrer">glTFの線形ブレンドスキニング</a></p><h2 id="fkとikは、姿勢を決める方法" tabindex="-1">FKとIKは、姿勢を決める方法 <a class="header-anchor" href="#fkとikは、姿勢を決める方法" aria-label="Permalink to &quot;FKとIKは、姿勢を決める方法&quot;">​</a></h2><p>**FK（順運動学）**では、肩や肘の角度などを決め、親子の変換から手の位置を求めます。**IK（逆運動学）**では、「手をこの位置へ持っていく」という目標から、関節の向きを求めます。足を地面へ合わせる、手を取っ手へ合わせる、といった用途があります。到達できる範囲や関節の制約も設定に関わります。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/InverseKinematics.html" target="_blank" rel="noreferrer">UnityのFKとIK</a></p><p>キーで作った姿勢を再生した後にIKで足元を調整するなど、複数の方法を組み合わせられます。Unityの標準Humanoid IKなど、利用できる機能にはリグの種類や設定の条件があります。制作ツールのリグを取り込むときは、書き出される骨格やアニメーションの内容も確認します。<a href="https://docs.unity3d.com/6000.0/Documentation/Manual/InverseKinematics.html" target="_blank" rel="noreferrer">UnityのHumanoid IKの条件</a></p><h2 id="骨につけた物と、変形する表面" tabindex="-1">骨につけた物と、変形する表面 <a class="header-anchor" href="#骨につけた物と、変形する表面" aria-label="Permalink to &quot;骨につけた物と、変形する表面&quot;">​</a></h2><p>手の子に剣のオブジェクトを付ければ、手の動きに剣を追従させられます。剣全体を一つのまとまりとして動かす構成と、腕の頂点を複数の骨で変形する構成は、別々に用意できます。<a href="https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#joint-hierarchy" target="_blank" rel="noreferrer">glTFのジョイントに付くノード</a> · <a href="/study/game/basics/scenes-and-components.html">シーンと親子関係</a></p><p>物理シミュレーションや当たり判定に使う形は、<a href="/study/game/basics/collisions-and-physics.html">コライダーとRigidbody</a>で確認できます。姿勢を時間に沿って再生する仕組みは<a href="/study/graphics/basics/keyframes-and-animation.html">キーフレームとアニメーション</a>へ進みます。</p><h2 id="変形した形を確認する" tabindex="-1">変形した形を確認する <a class="header-anchor" href="#変形した形を確認する" aria-label="Permalink to &quot;変形した形を確認する&quot;">​</a></h2><p>曲げたときの形を確認するときは、骨格の姿勢、影響する骨の番号、頂点のウェイトを順に見ます。基準姿勢では自然に見えても、肘を大きく曲げると境目がつぶれる場合があるため、ゲームで使う姿勢の範囲を試します。</p>',21)])])}const f=e(i,[["render",o]]);export{p as __pageData,f as default};
